from functools import lru_cache
from math import comb,factorial
from fractions import Fraction

@lru_cache(None)
def walks(a,b,c,last):
 if min(a,b,c)<0:return 0
 if a+b+c==0:return int(last!=0)
 return (walks(a-1,b,c,0) if last!=0 and a else 0)+(walks(a,b-1,c,1) if last!=1 and b else 0)+(walks(a,b,c-1,2) if last!=2 and c else 0)
@lru_cache(None)
def h2(a,b,c):
 z=sorted((a,b,c),reverse=True);a,b,c=z
 if b==0:return 0
 return factorial(a-1)*factorial(b)*factorial(c)*walks(a-1,b,c,0)
def poly(q):
 p=[1]+[0]*q
 for s in range(1,q+1):
  for k in range(1,s+1):p[k]+=comb(q,s)*factorial(s)*comb(s-1,k-1)//factorial(k)
 return p

def conv(a,b):
 c=[0]*(len(a)+len(b)-1)
 for i,x in enumerate(a):
  for j,y in enumerate(b):c[i+j]+=x*y
 return c

def cyc(a,b,c,q):
 p=[1]
 for _ in range(a//q):p=conv(p,poly(q))
 p=conv(p,poly(a%q))
 ans=sum(x*comb(b,l)*comb(c,m)*h2(k,l,m) for k,x in enumerate(p) for l in range(b+1) for m in range(c+1))
 ans-=a*b+a*c+b*c
 # cycles entirely within internal cliques
 for s in [q]*(a//q)+[a%q]:
  ans+=sum(comb(s,k)*factorial(k-1) for k in range(3,s+1))
 assert ans%2==0
 return ans//2
for q in (2,3,4):
 print('q=',q,poly(q))
 for a in range(q*2,q*9,q):
  x=cyc(a,a,a,q);y=cyc(a+1,a,a-1,q)
  print(a, float(Fraction(y,x)-1), 'shift better', y>x)

from functools import lru_cache
from itertools import combinations,combinations_with_replacement

def embeds_power(k,p,caps,removed=()):
 removed=set(removed)
 @lru_cache(None)
 def f(i,last,sizes):
  if i==k:return ()
  if i in removed:
   ans=f(i+1,last,sizes)
   return (None,)+ans if ans is not None else None
  seen=set()
  for c,cap in enumerate(caps):
   state=(cap,last[c],sizes[c])
   if state in seen:continue
   seen.add(state)
   ns=sizes[c]+1 if i-last[c]<=p else 1
   if ns>cap:continue
   ll=list(last);ss=list(sizes);ll[c]=i;ss[c]=ns
   ans=f(i+1,tuple(ll),tuple(ss))
   if ans is not None:return (c,)+ans
  return None
 return f(0,(-k,)*len(caps),(0,)*len(caps))

def partvec(total,r,low=0):
 if r==0:
  if total==0:yield ()
  return
 for i in range(low,total+1):
  for t in partvec(total-i,r-1,i):yield (i,)+t

for r in range(2,7):
 q=(r+2)//2
 k=(r+1)*q+(r if r%2 else 0)
 print('r',r,'path length',k)
 for u in range(r//2+1):
  for ds in partvec(r-2*u,r):
   caps=tuple(d+1 for d in ds)
   witness=None
   for rem in combinations(range(k),u):
    coloring=embeds_power(k,r,caps,rem)
    if coloring is not None:
     witness=(rem,coloring);break
   print(' universal',u,'ds',ds,'FREE',witness is None)

